{
  "作品名": "喜马拉雅的回响·第一集·翠苏里河畔",
  "分镜序列": [
    {
      "编号": 1,
      "类型": "文戏：8秒",
      "标题": "翠苏里河谷-晨光中的日常",
      "时间段": [
        "极缓推入大全景。朝阳映照翠苏里河谷，河面泛金，层层梯田沿山坡铺展，几座农舍的炊烟笔直升入浅蓝天空。远景喜马拉雅雪峰被晨光染成浅粉色，山腰薄雾如纱。河岸石头旁，苏青禾的军绿色双肩背包静静放着，植物标本夹翻开在旁，白色标签纸边缘在微风中轻轻卷动。画外音（男生旁白）平静地响起：<d>[中文] 这是再普通不过的一天。没有人知道，几个小时后，一切都会改变。</d>"
      ],
      "环境音": "河水潺潺流淌，远处公鸡断续打鸣，风吹过稻田的沙沙声，纸张被风卷动的轻响。",
      "BGM": "轻柔原声吉他单音循环，节奏舒缓，音量极低，仅作底色。"
    },
    {
      "编号": 2,
      "类型": "文戏：7秒",
      "标题": "河岸灌木丛-苏青禾监测植被异常",
      "时间段": [
        "切至近景，苏青禾蹲在河岸灌木丛旁，几缕碎发被晨风吹拂。她戴着户外手套的指尖捏起一片枯黄的叶片，举到眼前细看，眉骨微皱。她翻开植物标本夹，用笔在白色标签纸上快速记录，笔尖划过纸面的声音清晰可闻。她抬头望向雪山方向，声音清澈稍快，像在跟数据说话：<d>[中文] 这个海拔的杜鹃不应该八月黄叶……不对劲。</d> 她将叶片轻轻夹入标本夹，合上帆布封面，目光仍锁着远处的冰川。"
      ],
      "环境音": "笔尖在纸面上快速书写的沙沙声，风吹灌木叶片的摩挲声，河水持续的低响。",
      "BGM": "吉他延续，单音长笛加入，音色清亮中带着些许不安。"
    },
    {
      "编号": 3,
      "类型": "文戏：6秒",
      "标题": "刘承泽家院子-清晨道别",
      "时间段": [
        "切至刘承泽家院子，中景。刘承泽穿着深蓝色工装从屋里出来，一只脚踏下石阶，正低头系鞋带。林秀兰站在门口，一只手扶着门框，另一只手递过用布包好的饭盒，手腕上红绳手链微微晃动。她声音温润柔和：<d>[中文] 带上吧，中午别饿着。</d> 刘承泽接过饭盒，抬眼看她，嗓音沙哑带着浅笑：<d>[中文] 你每次都这么说。</d> 林秀兰笑了笑没接话，目光在他脸上停了一瞬——比平时长了一拍。她抬手拂掉他肩上的灰，那只手在空中慢了半秒，像在触碰什么不可言说的事。"
      ],
      "环境音": "远处隐约传来水电站汽笛声，院子里晾衣绳上衣物被风吹动的布面拍打声，饭盒放入帆布包时金属轻碰的闷响。",
      "BGM": "柔和弦乐拨弦，温暖旋律中带一丝不易察觉的凝重。"
    },
    {
      "编号": 4,
      "类型": "文戏：7秒",
      "标题": "加德满都气象站-赵恒的异常记录",
      "时间段": [
        "切至气象站办公室，中景框住赵恒的背影。他面对电脑屏幕，晨光从窗户斜入照亮桌面的文件堆。镜头缓慢推近，显示屏幕上的温度曲线图——红线明显高于往年虚线。赵恒的手指悬停在鼠标上，眉头紧锁，嘴唇微张。他翻看旁边的黑色皮革封面气象数据笔记本，用笔在当天日期旁画了个圈，低声说：<d>[中文] 比历史同期高了3.2度……这不对劲。</d> 他身后墙上的挂钟指针指向7点30分。"
      ],
      "环境音": "电脑风扇低鸣，窗外偶尔传来加德满都早市的嘈杂声，笔记本翻页的纸张声，挂钟秒针走动的滴答声。",
      "BGM": "吉他延续，单音小提琴加入，音色微颤，暗示不安。"
    },
    {
      "编号": 5,
      "类型": "文戏：6秒",
      "标题": "气象站-赵恒致电上级被拒",
      "时间段": [
        "近景，赵恒拿起电话听筒贴在耳边，眼镜片反射着屏幕的蓝光。他说话时音量比平时低了一度：<d>[中文] 长官，冰川融速数据异常……比去年同期的峰值还高。要不要发预警？</d> 他停顿聆听，表情逐渐失望，嘴唇抿紧，手中的笔在指尖转了一圈后放下，轻声应道：<d>[中文] 知道了，记录在案。</d> 他挂断电话，手指在桌面上无意识地敲了两下，目光落在屏幕上的曲线图，画面缓缓虚化。"
      ],
      "环境音": "电话拨号音，听筒中传来模糊的回应声，挂断后的电子蜂鸣。",
      "BGM": "小提琴单音持续拉长，音调渐高，制造紧张余韵。"
    },
    {
      "编号": 6,
      "类型": "文戏：7秒",
      "标题": "水电站控制室-沈静言的清晨",
      "时间段": [
        "切至水电站控制室，中景。沈静言坐在靠左的工位上，白色翻领衬衫袖口整齐卷到小臂中段。她将平板电脑立在桌上，手指在屏幕上滑动查看当天的设备巡检安排，指尖停顿在一处标注红框的数据上。身后有工友路过跟她打招呼，她没回头，只抬手示意了一下，目光仍锁在屏幕上。她端起水杯抿了一口，放下时杯底与桌面碰出一声轻响，左手腕的细金手链滑过袖口边缘。"
      ],
      "环境音": "控制室设备的低频嗡鸣，平板点击的电子音，远处对讲机通话的模糊人声，水杯碰桌面的轻响。",
      "BGM": "稳定的钢琴单音重复，象征工作秩序，略带机械感。"
    },
    {
      "编号": 7,
      "类型": "文戏：8秒",
      "标题": "水电站控制室-刘承泽与沈静言交接",
      "时间段": [
        "切至控制台另一侧，刘承泽抱着安全帽走过来，在沈静言工位旁边停下。他微微俯身看了看平板屏幕，语气平常：<d>[中文] 今天振动数据有什么异常吗？</d> 沈静言偏头看了他一眼，将平板往他那边转了一小角，语速稳定无波：<d>[中文] 2号涡轮的区间波动比上周高了一点，但还没超阈值。</d> 指尖在曲线上横划了一下，收回手，目光重新落回屏幕。刘承泽点头直起身：<d>[中文] 盯紧点。</d> 他转身朝门口走去，沈静言抬眼望了一眼他的背影，嘴唇微动似想说什么，但没出声，低下头继续滑动屏幕。"
      ],
      "环境音": "工装裤布料摩擦声，平板屏幕滑动的电子音，远处压力阀排气的咝咝声。",
      "BGM": "钢琴延续，加入隐蔽的电子合成器长音，暗示潜在危机。"
    },
    {
      "编号": 8,
      "类型": "文戏：7秒",
      "标题": "盘山公路-罗大勇和孩子们",
      "时间段": [
        "切至盘山公路，过肩镜头从罗大勇的蓝色棒球帽后方看向前方。黄色校车在弯道行驶，后视镜里映出一张张孩子的笑脸，其中一个女孩手里攥着一朵黄色野花，花瓣边缘有些蔫了。罗大勇侧头喊：<d>[中文] 安全第一，小子。坐稳了！</d> 孩子们哄笑，前座一个小男孩探头：<d>[中文] 罗叔叔，能开快一点吗？我想看新出生的小羊！</d> 阳光透过车窗洒在孩子们脸上，女孩低头闻了闻那朵蔫了的花，嘴角抿了一下。"
      ],
      "环境音": "校车引擎声，孩子们的嬉闹声，花朵被捏动时干燥叶片碎裂的微弱声响，风声从半开车窗灌入。",
      "BGM": "轻快的口哨旋律，配合车轮节奏，明朗温馨。"
    },
    {
      "编号": 9,
      "类型": "文戏：8秒",
      "标题": "加德满都郊外民居-陈仲安与林秀兰视频道别",
      "时间段": [
        "切至加德满都郊外民居，中景双人构图。林秀兰站在门口，手机举在耳边，手机屏幕里是陈仲安穿绿色夹克的笑脸。她说话时手指无意识地绕了绕垂落的发丝：<d>[中文] 午饭带了吗？别又忙得忘记吃。</d> 陈仲安在屏幕中笑着回应：<d>[中文] 带了。你放心。</d> 林秀兰低头看了看自己手腕的红绳手链，抬头补充：<d>[中文] 晚上早点回来，我给你做了你最爱吃的……</d> 陈仲安点头：<d>[中文] 好。</d> 林秀兰在挂断前多看了屏幕两秒，像是要把那张脸多留一会儿。挂断后，她轻轻拨了一下手链上的小铜铃，铜铃发出一声几乎听不见的轻响。"
      ],
      "环境音": "手机通话的电子音，铜铃轻响，厨房里锅盖碰锅沿的声音，远处有狗叫声。",
      "BGM": "钢琴慢板，温暖柔和，略带一丝离别前的不舍。"
    },
    {
      "编号": 10,
      "类型": "文戏：9秒",
      "标题": "村口大树-杜守山的预言与苏青禾偶遇",
      "时间段": [
        "切至村口菩提树下，低角度近景拍摄杜守山侧面，他拄着竹拐杖，盯着远处的雪山。苏青禾背着军绿色背包从河岸方向走来，在树前停住，弯腰系了系松开的登山鞋鞋带。一个年轻人走近杜守山：<d>[中文] 杜爷爷，看什么呢？</d> 杜守山缓缓转头，声音沙哑：<d>[中文] 山在呻吟。我活了97年，从没听过这样的声音。</d> 年轻人笑：<d>[中文] 山怎么会呻吟？您听错了吧。</d> 苏青禾系好鞋带直起身，目光从杜守山身上掠过，又看了看远处的雪山，嘴唇动了动没说话，手无意识地按了按胸前挂着的小型望远镜。杜守山注意到了她的动作，目光在她脸上停了一瞬，像在辨认什么，随即收回目光继续望向雪山。"
      ],
      "环境音": "风吹树叶沙沙声，远处雪崩般的沉闷回响（仅一瞬）被鸟鸣盖过，登山鞋踩过落叶的干裂声。",
      "BGM": "低音大提琴持续颤音，营造不祥预感，同时加入笛声的模糊线条。"
    },
    {
      "编号": 11,
      "类型": "文戏：6秒",
      "标题": "山间小路-苏青禾发现土壤异常",
      "时间段": [
        "切至山间小路，近景跟拍苏青禾行走。她的步伐快而稳，登山靴踩过碎石，忽然停下——路边一株蕨类植物叶片边缘卷曲发褐，整株姿态不自然地倒向一侧。她蹲下来，从军绿色背包侧面抽出放大镜贴近叶片细看，眉心越皱越紧。她掏出手机打开数据记录App，对准植物拍照，轻声自语：<d>[中文] 根际土壤水分流失太快……这个位置不该这样的。</d> 她抬头望向山坡上方，裸露的岩石表面有新鲜碎屑痕迹，像是最近才暴露出来。她咽了一下，收起手机站起身，动作比刚才慢了一些。"
      ],
      "环境音": "登山鞋踩碎石声，放大镜金属柄碰触叶片时的轻响，手机拍照的电子快门声。",
      "BGM": "长笛延续单音，音色逐渐变暗，如薄云遮日。"
    },
    {
      "编号": 12,
      "类型": "文戏：8秒",
      "标题": "喜马拉雅冰川-不祥的寂静与裂隙",
      "时间段": [
        "切换至航拍大全景，喜马拉雅冰川俯视镜头缓慢下降。蓝白色冰面布满放射状裂缝，融水汇成溪流在冰舌边缘形成细小瀑布。光线明亮刺眼，冰面中部有一片阴影——一条宽达数米的深色裂隙，边缘冰层微微向外倾斜，裂隙内部融水呈浑浊的灰白色，与上方洁净的蓝冰形成刺眼对比。突然，一声沉闷的断裂声从冰川深处传来——像大地在叹息。一只停驻在裂隙边缘的灰色岩鸽猛然振翅飞走。画面微微震动。"
      ],
      "环境音": "寂静中水滴落入水潭的清脆声，随即一声低频、深远的冰裂声，类似闷雷，随后是翅膀急促扑棱的声音。",
      "BGM": "所有音乐骤停，只留环境音和那声冰裂，以及翅膀远去的振频声。"
    },
    {
      "编号": 13,
      "类型": "文戏：5秒",
      "标题": "黑屏-字幕科学预警",
      "时间段": [
        "黑屏，白色字幕缓缓浮现，无背景音乐，只有极轻的电流底噪。字幕内容：‘2026年3月，国际山地综合发展中心（ICIMOD）发布《2026年兴都库什喜马拉雅冰川展望》，警告自1975年以来当地冰川厚度最多已消融达27米，2000年以来消退速度翻倍，冰川正逼近不可逆转的退缩临界点。’"
      ],
      "环境音": "极低的电流嗡鸣。",
      "BGM": "无。"
    },
    {
      "编号": 14,
      "类型": "文戏：7秒",
      "标题": "气象站-赵恒再次查看报告",
      "时间段": [
        "切回气象站，近景。赵恒从抽屉里取出ICIMOD报告打印件，翻到有红字标注的一页，食指指腹划过‘威胁下游近20亿居民’一行，在纸面留下短暂压痕。他再次拿起电话拨号，语速略快：<d>[中文] 长官，我还是觉得应该发预警。ICIMOD的报告说了——</d> 他停顿，听到对方回应，表情僵住，喉结微微滚动，然后低声说：<d>[中文] 知道了……但我们不能因为‘可能’就制造恐慌？</d> 他缓缓放下听筒，没有立刻挂断，手指悬在叉簧上停了半拍，才轻轻按下。双眼直盯着窗外，玻璃上映出他自己模糊的轮廓。"
      ],
      "环境音": "电话忙音，纸张被指腹摩擦的细微沙沙声，远处隐约的城市喧嚣。",
      "BGM": "单簧管吹奏不和谐音程，缓慢、压抑。"
    },
    {
      "编号": 15,
      "类型": "文戏：7秒",
      "标题": "水电站控制室-沈静言独自查看地质数据",
      "时间段": [
        "切至水电站控制室，近景。沈静言独自坐在工位前，其他人已去参加晨会。她将平板电脑连上外部数据终端，屏幕上跳出地质震动监测图——近30天的高频微震事件数量以柱状图呈现，每一天的柱子都比前一天高一些。她的指尖停在最后一根柱子上，嘴唇微微抿紧。她拔下连接线，平板屏幕暗了一瞬又重新亮起，她在设备记录页面的备注栏里敲了一个词：‘注意’，随后加了一个问号。她端起水杯喝了一口又放下，指尖在桌沿轻轻敲了两下——节奏平直均匀，像在数拍子。"
      ],
      "环境音": "数据终端连接时的电子提示音，平板键盘的轻微点击声，水杯放下时与桌面碰出的轻响，远处其他人讲话的回声。",
      "BGM": "电子合成器的中低音层，平稳但略显紧张，暗示数据攀升。"
    },
    {
      "编号": 16,
      "类型": "文戏：8秒",
      "标题": "水电站隧道-陈仲安发现管壁裂痕",
      "时间段": [
        "切至水电站隧道内部，中景手持微晃镜头。陈仲安戴安全帽，手持手电筒照向管壁。一条细微的裂痕在灯光下清晰可见，裂缝边缘有薄薄的白色盐析物。他伸出戴手套的手指沿裂缝走向缓缓触摸——指套碰到一片微微凸起的锈迹。刘承泽从后面走来：<d>[中文] 陈工，怎么了？</d> 陈仲安未转头，目光仍盯着裂痕，声音低沉缓慢：<d>[中文] 这里的应力不太对。可能是最近地质活动造成的。</d> 刘承泽凑近看，手电筒光柱与陈仲安的光柱在裂缝处交汇，形成一个更亮的圆斑。陈仲安直起身补充：<d>[中文] 记录一下，让结构工程师来看看。现在就去。</d> 最后三个字比前面重了一些。"
